import {getDocument,GlobalWorkerOptions} from './vendor/pdf.mjs';
GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;
const disclosure=document.querySelector('#resume-disclosure'),canvas=document.querySelector('#resume-canvas'),scroll=document.querySelector('.pdf-scroll'),status=document.querySelector('#resume-status');let doc=null,loading=false,pageNumber=1,scale=1,task=null,version=0;
async function render(){if(!doc||!disclosure.open)return;const token=++version;if(task){task.cancel();try{await task.promise}catch{}}const page=await doc.getPage(pageNumber);if(token!==version)return;const viewport=page.getViewport({scale}),ratio=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(viewport.width*ratio);canvas.height=Math.floor(viewport.height*ratio);canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';task=page.render({canvasContext:canvas.getContext('2d'),viewport,transform:ratio===1?null:[ratio,0,0,ratio,0,0]});try{await task.promise;if(token!==version)return;status.textContent='';document.querySelector('#resume-pages').textContent=pageNumber+' / '+doc.numPages;document.querySelector('#resume-zoom').textContent=Math.round(scale*100)+'%';document.querySelector('#resume-prev').disabled=pageNumber<=1;document.querySelector('#resume-next').disabled=pageNumber>=doc.numPages;canvas.setAttribute('aria-label','Resume page '+pageNumber+' of '+doc.numPages)}catch(e){if(e.name!=='RenderingCancelledException')status.textContent='Unable to render. Use Open full screen above.'}}
async function fit(){if(!doc)return;const page=await doc.getPage(pageNumber),v=page.getViewport({scale:1});scale=Math.max(.3,Math.min(2,(scroll.clientWidth-32)/v.width));await render()}
async function open(){if(doc){await render();return}if(loading)return;loading=true;status.textContent='Loading resume…';try{doc=await getDocument({url:'assets/Qingyuan-Tian-Resume.pdf'}).promise;await fit()}catch(e){status.textContent='Unable to load the viewer. Use Open full screen or Download PDF above.'}finally{loading=false}}
disclosure.addEventListener('toggle',()=>{if(disclosure.open)open()});document.querySelector('#resume-zoom-in').onclick=()=>{scale=Math.min(3,scale+.2);render()};document.querySelector('#resume-zoom-out').onclick=()=>{scale=Math.max(.3,scale-.2);render()};document.querySelector('#resume-fit').onclick=fit;document.querySelector('#resume-prev').onclick=()=>{if(pageNumber>1){pageNumber--;render()}};document.querySelector('#resume-next').onclick=()=>{if(doc&&pageNumber<doc.numPages){pageNumber++;render()}};if(disclosure.open)open();
